import React from 'react';
import { useNavigate } from 'react-router-dom';

function ProductTable({ products, setProducts }) {
  const navigate = useNavigate();

  const handleDelete = (id) => {
    const updated = products.filter(p => p.id !== id);
    setProducts(updated);
    localStorage.setItem('products', JSON.stringify(updated));
  };

  return (
    <table>
      <thead>
        <tr>
          <th>ID</th>
          <th>Product Name</th>
          <th>Price</th>
          <th>Stocks</th>
          <th>Actions</th>
        </tr>
      </thead>
      <tbody>
        {products.map(p => (
          <tr key={p.id}>
            <td>{p.id}</td>
            <td>{p.name}</td>
            <td>{p.price}</td>
            <td>{p.stocks}</td>
            <td>
              <span className="action-btn" onClick={() => navigate(`/admin/edit-product/${p.id}`)}>✏️</span>
              <span className="action-btn" onClick={() => handleDelete(p.id)}>🗑️</span>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export default ProductTable;
